#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Every tracked shell script must carry the executable bit in the tree.
#
# run_local_tests.sh's step() executes tests/check_*.sh directly, and the
# fork's linux-checks runs that script on Ubuntu, so a .sh committed as
# 100644 answers those steps with exit 126. A checkout whose git carries
# core.filemode=false — the Windows box (docs/agents/windows-toolchain.md)
# — never records the filesystem bit, so scripts added there land 100644
# unless they are staged with `git update-index --chmod=+x`; the Windows
# gate cannot see the defect either, because verify_windows.sh invokes the
# same scripts through bash.exe. This gate is the check neither box runs
# by accident.
#
# Modes:
#   (default)  audit every tracked *.sh in the index.
#   staged     audit only the files staged for the next commit — run by
#              tests/hooks/pre-commit so the defect dies before the
#              commit is formed.
#
# Exit codes:
#   0   every *.sh (or staged addition) is 100755
#   1   at least one is not
#   125 not a git repository
set -u

mode="${1:-tree}"
# The audit targets the current repository, which is where every caller
# stands: the pre-commit hook and the gate scripts cd to their root first.
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || exit 125

bad=0
report() {
    printf '%s: %s is %s; fix with: git update-index --chmod=+x %s\n' \
        "$mode" "$1" "$2" "$1" >&2
    bad=1
}

if [ "$mode" = "staged" ]; then
    git rev-parse --verify HEAD >/dev/null 2>&1 || exit 125
    # --raw records the index mode per added/copied/modified path, so the
    # audit sees what would actually be committed, not the working file.
    # With -z each entry is a colon-prefixed meta record followed by its
    # path as a separate NUL-delimited field.
    while IFS= read -r -d '' meta && IFS= read -r -d '' path; do
        dest_mode=$(printf '%s' "$meta" | awk '{print $2}')
        [ "$dest_mode" = "100755" ] || report "$path" "$dest_mode"
    done < <(git diff --cached --raw -z --diff-filter=ACM -- '*.sh')
else
    while IFS= read -r line; do
        tree_mode=${line%% *}
        path=${line#*$'\t'}
        [ "$tree_mode" = "100755" ] || report "$path" "$tree_mode"
    done < <(git ls-files --stage -- '*.sh')
fi

exit "$bad"
